// Авторские экзаменационные задачи. Ответы заданы до запуска компилятора.
export const exam=[];
let topic='';
function section(name){topic=name;}
function q(title,body,answer,wrong,why,decl='',imports='fmt',kind='run'){
 const correct=kind==='compile'?'Не компилируется':answer;
 const choices=wrong.map(v=>v===''?'Пустой вывод':v);const correctIndex=(601+exam.length)%4;choices.splice(correctIndex,0,correct);
 if(choices.length!==4||new Set(choices).size!==4)throw Error(title+': нужны четыре разных ответа');
 exam.push({id:601+exam.length,topic,title:'Экзамен: '+title,source:`package main\n${imports?'import ('+imports.split(',').map(s=>'"'+s+'"').join(';')+')\n':''}${decl}\nfunc main(){${body}}\n`,kind,answer,why,choices,correctIndex});
}
function bad(title,body,diagnostic,wrong,why,decl='',imports='fmt'){q(title,body,diagnostic,wrong,why,decl,imports,'compile');}
section('Экзамен · Вычисление выражений, defer и recover');
q('Снимок аргумента и позднее чтение','x:=2;defer fmt.Println(x);defer func(){fmt.Println(x)}();x=9','9\n2',['2\n9','9\n9','2\n2'],'Аргумент Println сохраняется при defer; замыкание читает x при исполнении. Отложенные вызовы выполняются в обратном порядке.');
q('Именованный результат после return','fmt.Println(f())','7',['3','4','Не компилируется'],'return записывает 3 в именованный результат; defer прибавляет 4 перед передачей результата вызывающему.', 'func f()(n int){defer func(){n+=4}();return 3}');
q('Копия результата до defer','fmt.Println(f())','3',['7','0','Не компилируется'],'Неименованный результат получает копию x до выполнения defer; последующее изменение локальной x на эту копию не влияет.','func f()int{x:=3;defer func(){x+=4}();return x}');
q('Метод в defer сохраняет указатель','p:=&N{2};defer p.Show();p.V=8;p=&N{9}','8',['2','9','panic'],'Получатель вычисляется сразу: defer хранит указатель на первый N. Изменение его поля видно, переприсваивание p — нет.','type N struct{V int};func(n *N)Show(){fmt.Println(n.V)}');
q('Значимый получатель в defer','p:=&N{2};defer p.Show();p.V=8','2',['8','0','Не компилируется'],'Для метода с получателем N при регистрации defer копируется значение *p. Последующая запись в поле исходного объекта не меняет копию.','type N struct{V int};func(n N)Show(){fmt.Println(n.V)}');
q('Возвращаемый срез и отложенная запись','fmt.Println(f())','[7 2]',['[1 2]','[7]','panic'],'Возвращается копия заголовка среза, но массив остаётся общим с локальным s; defer меняет его первый элемент.','func f()[]int{s:=[]int{1,2};defer func(){s[0]=7}();return s}');
q('Отложенный append меняет локальный заголовок','fmt.Println(f())','[1]',['[1 2]','[]','panic'],'Результат уже содержит длину 1. Append в defer меняет локальный заголовок, даже если использует тот же массив.','func f()[]int{s:=make([]int,1,2);s[0]=1;defer func(){s=append(s,2)}();return s}');
q('Непрямой recover не останавливает panic','defer func(){fmt.Println(recover())}();defer func(){helper()}();panic("boom")','<nil>\nboom',['boom\n<nil>','<nil>\n<nil>','boom'],'recover в helper вызван не непосредственно отложенной функцией и возвращает nil. Внешний defer перехватывает исходную панику.','func helper(){fmt.Println(recover())}');
q('Вторая паника во время раскрутки','defer func(){fmt.Println(recover())}();defer func(){panic("second")}();panic("first")','second',['first','first\nsecond','<nil>'],'Внутренний defer порождает новую активную панику. Внешний recover получает её значение second, а не first.');
q('Результат после перехвата panic','fmt.Println(f())','12',['0','5','panic'],'Именованный результат сначала равен 5, затем defer перехватывает панику и записывает 12. Выполнение тела после panic не возобновляется.','func f()(n int){n=5;defer func(){if recover()!=nil{n=12}}();panic("x")}');
q('Nil-функция в defer','defer func(){fmt.Println(recover()!=nil)}();var f func();defer f();fmt.Println("body")','body\ntrue',['true','body\nfalse','Не компилируется'],'Nil-функция регистрируется без вызова. Паника возникает при исполнении defer после печати body и перехватывается внешним defer.');
q('Фабрика отложенной функции','defer factory()();fmt.Println("body")','factory\nbody\ndeferred',['body\nfactory\ndeferred','factory\ndeferred\nbody','Не компилируется'],'factory вызывается сразу, чтобы получить откладываемую функцию. Только возвращённый вызов переносится на выход.','func factory()func(){fmt.Println("factory");return func(){fmt.Println("deferred")}}');
q('Короткое замыкание сохраняет счётчик','n:=0;f:=func()bool{n++;return true};fmt.Println(false&&f(),true||f(),n)','false true 0',['false true 2','true true 2','false false 0'],'Правые операнды && и || вычисляются лишь при необходимости; оба вызова f пропускаются.');
q('Порядок вызовов в аргументах','n:=0;next:=func()int{n++;return n};fmt.Println(next(),next(),next())','1 2 3',['3 2 1','3 3 3','Порядок не определён'],'Вызовы функций в выражении вычисляются слева направо. Здесь каждый аргумент — вызов, без неоднозначного смешивания чтений и побочных эффектов.');
q('Множественное присваивание индекса','i:=0;a:=[]int{4,5};i,a[i]=1,9;fmt.Println(i,a)','1 [9 5]',['1 [4 9]','0 [9 5]','panic'],'Индекс левой части вычисляется до записей. Используется старое i=0, затем значения присваиваются слева направо.');
q('Swap с одинаковой ячейкой','a:=[]int{1};a[0],a[0]=2,3;fmt.Println(a)','[3]',['[2]','[1]','Не компилируется'],'Правые части вычисляются сначала, записи выполняются слева направо; вторая запись в ту же ячейку побеждает.');
q('Отложенный close и чтение','ch:=make(chan int,1);ch<-7;func(){defer close(ch)}();a,ok:=<-ch;b,more:=<-ch;fmt.Println(a,ok,b,more)','7 true 0 false',['0 false 0 false','7 false 0 false','deadlock'],'Close сохраняет буферизированные значения. Первое чтение успешно, второе из закрытого пустого канала возвращает ноль и false.');
q('Замыкание среза против аргумента','s:=[]int{1};defer func(){fmt.Println(s)}();defer fmt.Println(s);s=[]int{9}','[1]\n[9]',['[9]\n[9]','[1]\n[1]','[9]\n[1]'],'Println хранит старый заголовок среза. Замыкание читает переменную s после переприсваивания; LIFO определяет порядок строк.');
q('Defer внутри цикла','for i:=1;i<=3;i++{defer fmt.Print(i)}','321',['123','333','000'],'Аргументы вычисляются на каждой итерации и сохраняются отдельно. Отложенные вызовы выполняются после цикла в обратном порядке.');
bad('Результат recover без утверждения типа','defer func(){n:=recover();fmt.Println(n+1)}();panic(2)','invalid operation',['3','2','<nil>'],'recover возвращает any. Арифметика над интерфейсом запрещена; нужно утверждение типа или type switch.');
section('Экзамен · Области видимости, циклы и управление');
q('Тень переменной в if','x:=1;if x:=x+2;x>0{x++;fmt.Print(x," ")};fmt.Println(x)','4 1',['4 4','3 1','Не компилируется'],'Правая часть короткого объявления использует внешнее x; новое x живёт только в if и не меняет внешнее значение.');
q('Повторное объявление в том же блоке','x:=2;x,y:=x+1,x+4;fmt.Println(x,y)','3 6',['3 7','2 6','Не компилируется'],'y — новая переменная, поэтому := допустим. Обе правые части читают прежнее x=2 до присваивания.');
bad('Короткое объявление без нового имени','x:=2;x:=3;fmt.Println(x)','no new variables',['3','2','panic'],'В том же блоке := требует хотя бы одну новую переменную, отличную от _. Для изменения x нужно =.');
q('Тень функции len','len:=func(s string)int{return 99};fmt.Println(len("Go"))','99',['2','0','Не компилируется'],'Предопределённые идентификаторы можно затенять локальными объявлениями. Здесь вызывается пользовательская функция len.');
q('Range с := в Go 1.23','var fs []func()int;for _,v:=range []int{2,4,6}{fs=append(fs,func()int{return v})};fmt.Println(fs[0](),fs[1](),fs[2]())','2 4 6',['6 6 6','0 0 0','Порядок не определён'],'Начиная с Go 1.22 переменные итерации, объявленные через :=, создаются заново для каждой итерации.');
q('Range с = разделяет переменную','var fs []func()int;var v int;for _,v=range []int{2,4,6}{fs=append(fs,func()int{return v})};fmt.Println(fs[0](),fs[1](),fs[2]())','6 6 6',['2 4 6','0 0 0','Не компилируется'],'Знак = присваивает одной заранее объявленной переменной. Все замыкания после цикла читают её последнее значение.');
q('Адреса переменных итерации','var ps []*int;for _,v:=range []int{3,8}{ps=append(ps,&v)};fmt.Println(ps[0]==ps[1],*ps[0],*ps[1])','false 3 8',['true 8 8','false 8 8','true 3 3'],'При := переменные разных итераций различны и их адреса сохраняются в срезе. Они продолжают существовать после выхода из цикла.');
q('Обычный for и захваченный счётчик','var fs []func()int;for i:=0;i<3;i++{fs=append(fs,func()int{return i})};fmt.Println(fs[0](),fs[1](),fs[2]())','0 1 2',['3 3 3','1 2 3','Не компилируется'],'Правило Go 1.22 распространяется и на обычный for с объявлением в init: каждая итерация получает свой i.');
q('Range по целому определённого типа','var end N=4;var sum N;for i:=range end{sum+=i};fmt.Printf("%T %v",sum,sum)','main.N 6',['int 6','main.N 10','Не компилируется'],'Range по целому перебирает 0..n-1. Тип i совпадает с типом end, поэтому сложение с N допустимо.','type N int');
q('Отрицательная граница range','n:=-3;count:=0;for range n{count++};fmt.Println(count)','0',['3','-3','panic'],'Для целой границы <=0 итераций нет. Отрицательная переменная не вызывает панику.');
q('Switch без выражения и побочный эффект','n:=0;f:=func()bool{n++;return true};switch{case f():fmt.Print("a ");case f():fmt.Print("b ")};fmt.Println(n)','a 1',['a b 2','a 2','b 2'],'Switch выбирает первый истинный case; следующие условия не вычисляются, автоматического перехода нет.');
q('Fallthrough не проверяет условие','n:=1;switch n{case 1:fmt.Print("a ");fallthrough;case 99:fmt.Println("b")}','a b',['a','b','Не компилируется'],'Fallthrough передаёт управление телу следующего case без проверки его условия.');
q('Break выходит только из switch','n:=0;for i:=0;i<3;i++{switch i{case 1:break};n++};fmt.Println(n)','3',['1','2','0'],'Без метки break относится к ближайшему for, switch или select. Здесь он завершает switch, затем выполняется n++.');
q('Continue с меткой внешнего цикла','n:=0;Outer:for i:=0;i<3;i++{for j:=0;j<3;j++{if j==1{continue Outer};n++}};fmt.Println(n)','3',['9','6','1'],'На каждой внешней итерации счётчик увеличивается лишь при j=0; затем continue Outer начинает следующую итерацию внешнего цикла.');
bad('Goto через объявление','goto Done;x:=2;Done:fmt.Println(x)','jumps over declaration',['2','0','panic'],'Goto не может перескочить объявление переменной, которая оказалась бы в области видимости в точке назначения.');
q('Switch по типу в одиночном case','var x any=N(4);switch v:=x.(type){case N:fmt.Printf("%T %v",v,v+1);default:fmt.Print("other")}','main.N 5',['int 5','other','Не компилируется'],'При единственном типе в case переменная v получает этот статический тип. Определённый N сохраняется в арифметическом результате.','type N int');
q('Несколько типов в case сохраняют интерфейс','var x any=N(4);switch v:=x.(type){case N,int:_,ok:=v.(N);fmt.Println(ok)}','true',['false','4','Не компилируется'],'В case с несколькими типами статический тип v остаётся типом исходного интерфейса; утверждение v.(N) допустимо.','type N int');
bad('Переменная if недоступна после него','if x:=2;x>0{fmt.Print(x)};fmt.Println(x)','undefined: x',['22','2','0'],'Область видимости x из init ограничена самим if, включая ветви; следующий оператор уже вне этой области.');
q('Тень именованного результата и явный return','fmt.Println(f())','8',['0','3','Не компилируется'],'Локальное n затеняет именованный результат, но return n явно передаёт его значение в возвращаемый результат.','func f()(n int){if n:=8;n>0{return n};return}');
bad('Голый return под тенью результата','fmt.Println(f())','result parameter n not in scope',['8','0','panic'],'Голый return запрещён, когда именованный результат затенён другим объявлением в этой точке. Явный return n был бы допустим.','func f()(n int){if n:=8;n>0{return};return}');
section('Экзамен · Контракты интерфейсов и множества методов');
q('Any хранит nil-указатель на ошибку','var p *E;var e error=p;fmt.Println(e==nil,e.Error())','false empty',['true empty','false panic','Не компилируется'],'Интерфейс содержит динамический тип *E и nil-значение, поэтому не равен nil. Метод умеет обрабатывать nil-получателя.','type E struct{};func(e *E)Error()string{if e==nil{return "empty"};return "full"}');
q('Интерфейсный вызов метода копирует структуру','n:=N{3};var c Counter=n;fmt.Println(c.Inc(),n.V)','4 3',['4 4','3 3','Не компилируется'],'Метод с получателем-значением изменяет копию N. Ни объект внутри интерфейса, ни исходная переменная не получают запись.','type N struct{V int};func(n N)Inc()int{n.V++;return n.V};type Counter interface{Inc()int}');
q('Интерфейс держит живой указатель','n:=N{3};var c Counter=&n;n.V=8;fmt.Println(c.Inc(),n.V)','9 9',['4 3','9 8','Не компилируется'],'Динамическое значение — указатель на n; метод с указательным получателем меняет тот же объект.','type N struct{V int};func(n *N)Inc()int{n.V++;return n.V};type Counter interface{Inc()int}');
bad('Автоадресация не строит интерфейс','n:=N{};n.M();var x I=n;fmt.Println(x)','does not implement',['{}','0','panic'],'Вызов n.M() допускает автоадресацию адресуемой n. Присваивание интерфейсу не добавляет методы *N в множество методов N.','type N struct{};func(*N)M(){};type I interface{M()}');
q('Метод выражения и явный получатель','f:=(*N).Add;n:=N{5};fmt.Println(f(&n,3),n.V)','8 8',['8 5','3 8','Не компилируется'],'Метод-выражение превращает получатель в первый явный аргумент функции. Передан адрес n, поэтому поле изменяется.','type N struct{V int};func(n *N)Add(x int)int{n.V+=x;return n.V}');
q('Захват метода до замены интерфейса','var x I=N(2);f:=x.M;x=N(9);fmt.Println(f(),x.M())','2 9',['9 9','2 2','Не компилируется'],'Method value сохраняет текущий интерфейсный получатель. Переприсваивание x не меняет получатель, сохранённый в f.','type I interface{M()int};type N int;func(n N)M()int{return int(n)}');
q('Сравнение разных динамических типов','var a any=A(3);var b any=B(3);fmt.Println(a==b)','false',['true','panic','Не компилируется'],'Интерфейсы равны лишь при одинаковом динамическом типе и равных динамических значениях. A и B — разные определённые типы.','type A int;type B int');
q('Разные типы срезов в интерфейсах','var a any=[]int{1};var b any=[]string{"1"};fmt.Println(a==b)','false',['true','panic','Не компилируется'],'Сравнение сначала обнаруживает разные динамические типы. Оно не пытается сравнивать элементы несравнимых срезов и не паникует.');
q('Одинаковый тип несравнимых значений','defer func(){fmt.Println(recover()!=nil)}();var a any=[]int(nil);var b any=[]int(nil);fmt.Println(a==b)','true',['false','true\nfalse','Не компилируется'],'Равные динамические типы []int приводят к попытке сравнить срезы. Даже nil-срезы несравнимы друг с другом; recover печатает true.');
q('Nil-интерфейс против интерфейса со срезом','var a any;var b any=[]int{1};fmt.Println(a==b)','false',['true','panic','Не компилируется'],'У nil-интерфейса нет динамического типа. Типы различаются, поэтому сравнение даёт false без сравнения среза.');
q('Утверждение интерфейса расширяет доступ','var r R=N{};rw,ok:=r.(RW);fmt.Println(ok,rw.Write())','true 7',['false 0','true 3','Не компилируется'],'Утверждение к интерфейсу проверяет динамический тип N; он реализует оба метода, хотя исходный статический интерфейс раскрывал только Read.','type R interface{Read()int};type RW interface{Read()int;Write()int};type N struct{};func(N)Read()int{return 3};func(N)Write()int{return 7}');
bad('Ковариантности результатов методов нет','var f Factory=N{};fmt.Println(f.Make())','does not implement',['7','{}','panic'],'Make()N и Make()any — разные сигнатуры. Автоматического расширения типа результата при реализации интерфейса нет.','type Factory interface{Make()any};type N struct{};func(N)Make()N{return N{}}');
bad('Variadic меняет сигнатуру контракта','var x I=N{};fmt.Println(x.Sum([]int{1}))','does not implement',['1','0','panic'],'Параметры []int и ...int задают разные типы функций и методов, даже при одинаковом представлении аргументов внутри тела.','type I interface{Sum([]int)int};type N struct{};func(N)Sum(...int)int{return 1}');
q('Alias результата совместим с контрактом','var f F=N{};fmt.Println(f.Get())','6',['0','panic','Не компилируется'],'Alias I обозначает тот же тип int, поэтому Get()I полностью совпадает с требуемым Get()int.','type I=int;type F interface{Get()int};type N struct{};func(N)Get()I{return 6}');
q('Встроенный nil-указатель с безопасным методом','var w Wrapper;var i I=w;fmt.Println(i.OK())','true',['false','panic','Не компилируется'],'Wrapper со встроенным *N получает его методы. Продвинутый вызов передаёт nil в указательный метод, где это явно обработано.','type N struct{};func(n *N)OK()bool{return n==nil};type Wrapper struct{*N};type I interface{OK()bool}');
q('Встроенный nil и метод со значимым получателем','defer func(){fmt.Println(recover()!=nil)}();var w Wrapper;w.M()','true',['false','7','Не компилируется'],'Продвижение метода N.M через встроенный *N требует разыменования nil ещё до входа в тело метода.','type N struct{};func(N)M(){fmt.Println(7)};type Wrapper struct{*N}');
bad('Два продвинутых одноимённых метода','var i I=C{};fmt.Println(i.M())','ambiguous selector',['1','2','panic'],'На одной глубине встраивания M приходит из A и B. Неоднозначный селектор не обеспечивает реализацию I.','type A struct{};func(A)M()int{return 1};type B struct{};func(B)M()int{return 2};type C struct{A;B};type I interface{M()int}');
q('Явный метод снимает неоднозначность','var i I=C{};fmt.Println(i.M())','3',['1','2','Не компилируется'],'Собственный C.M имеет меньшую глубину и скрывает оба продвинутых метода. Интерфейс I реализован однозначно.','type A struct{};func(A)M()int{return 1};type B struct{};func(B)M()int{return 2};type C struct{A;B};func(C)M()int{return 3};type I interface{M()int}');
q('Функциональный тип реализует интерфейс','var h H=F(func(x int)int{return x*3});fmt.Println(h.Do(4))','12',['4','0','Не компилируется'],'Определённому функциональному типу F можно объявить методы. Его метод Do вызывает хранимую функцию, адаптируя её к интерфейсу.','type H interface{Do(int)int};type F func(int)int;func(f F)Do(x int)int{return f(x)}');
q('Nil-функция с методом проверки','var f F;var c Checker=f;fmt.Println(c==nil,c.Ready())','false false',['true false','false true','panic'],'Динамический тип F делает интерфейс ненулевым. Метод сравнивает функцию с nil, не вызывая её, поэтому паники нет.','type F func();func(f F)Ready()bool{return f!=nil};type Checker interface{Ready()bool}');
section('Экзамен · Generics: ограничения и вывод типов');
q('Ограничение среза сохраняет имя','x:=Copy(IDs{2,5});fmt.Printf("%T %v",x,x)','main.IDs [2 5]',['[]int [2 5]','main.IDs []','Не компилируется'],'S выводится как IDs, E как int. Возврат S сохраняет определённый тип, хотя копирование выполняется через append.','type IDs []int;func Copy[S ~[]E,E any](s S)S{return append(S(nil),s...)}');
q('Точный тип среза допускает именованный элемент','fmt.Println(First([]ID{7}))','7',['0','panic','Не компилируется'],'Ограничение []E требует точный тип среза. Здесь сам срез неименованный, а E выводится как определённый ID.','type ID int;func First[S []E,E any](s S)E{return s[0]}');
bad('Точный срез исключает именованный контейнер','fmt.Println(First(IDs{7}))','does not satisfy',['7','0','panic'],'У IDs базовый тип []int, но сам IDs не равен []int. Ограничению требуется ~[]E для допуска именованного контейнера.','type IDs []int;func First[S []E,E any](s S)E{return s[0]}');
q('Any удовлетворяет comparable, но значение опасно','defer func(){fmt.Println(recover()!=nil)}();fmt.Println(Equal[any]([]int{1},[]int{1}))','true',['false','true\ntrue','Не компилируется'],'Go 1.23 допускает any как аргумент comparable. Конкретные динамические срезы при == вызывают панику; это не статическая гарантия безопасности.','func Equal[T comparable](a,b T)bool{return a==b}');
q('Generic сравнивает разные динамические типы','fmt.Println(Equal[any](1,int64(1)))','false',['true','panic','Не компилируется'],'T явно задан как any, значения упакованы в интерфейсы. Их динамические типы int и int64 различаются.','func Equal[T comparable](a,b T)bool{return a==b}');
bad('Comparable не означает упорядоченность','fmt.Println(Less(1,2))','type parameter T is not comparable with <',['true','false','panic'],'Comparable разрешает == и !=, но включает структуры, указатели и другие типы без операции <. Тело проверяется для всего множества типов.','func Less[T comparable](a,b T)bool{return a<b}');
q('Явный тип управляет нетипизированным литералом','fmt.Printf("%T %v",Pick[int8](3,4),Pick[int8](3,4))','int8 3',['int 3','int8 4','Не компилируется'],'Явный T=int8 задаёт контекст для обоих константных аргументов. Они представимы в int8, результат имеет тот же тип.','func Pick[T any](a,b T)T{return a}');
bad('Явный тип не разрешает переполнение константы','fmt.Println(Id[int8](128))','overflows',['-128','128','panic'],'Константа 128 не представима в int8. Это ошибка на месте вызова, а не переполнение уже типизированной переменной.','func Id[T any](x T)T{return x}');
q('Объединение числовых нетипизированных аргументов','fmt.Printf("%T",Pick(1,2.5))','float64',['int','float32','Не компилируется'],'Вывод типов объединяет виды нетипизированных числовых аргументов. Общим типом по умолчанию становится float64.','func Pick[T any](a,b T)T{return a}');
bad('Nil не даёт информации для T','fmt.Println(Id(nil))','cannot infer',['<nil>','0','panic'],'Нетипизированный nil не имеет типа по умолчанию. Без явной инстанциации или другого типизированного аргумента вывести T нельзя.','func Id[T any](x T)T{return x}');
q('Nil при известном типе указателя','fmt.Println(Id[*int](nil)==nil)','true',['false','panic','Не компилируется'],'T задан явно как *int, поэтому nil получает допустимый указательный контекст и возвращается без разыменования.','func Id[T any](x T)T{return x}');
q('Generic-функция выводится из типа назначения','var f func(string)string=Id;fmt.Println(f("go"))','go',['','panic','Не компилируется'],'Go 1.23 умеет выводить параметры обобщённой функции из целевого типа функции в присваивании. Здесь T=string.','func Id[T any](x T)T{return x}');
bad('Тип результата вызова не выводит T','var x int=Zero();fmt.Println(x)','cannot infer',['0','<nil>','panic'],'Контекст присваивания результата обычного вызова не используется для вывода T. Нужно Zero[int](); это отличается от присваивания самой функции.','func Zero[T any]()T{var z T;return z}');
q('Частичная инстанциация оставляет вывод второго типа','fmt.Printf("%T",Pair[int](1,"x"))','struct { A int; B string }',['struct { A int; B interface {} }','string','Не компилируется'],'Задан первый параметр A; B выводится из второго аргумента. Результат — неименованная структура с конкретными типами полей.','func Pair[A,B any](a A,b B)struct{A A;B B}{return struct{A A;B B}{a,b}}');
bad('Метод отсутствует в ограничении с базовым типом','fmt.Println(Call(N(1)))','x.M undefined',['1','0','panic'],'~int допускает все типы с базовым int, включая типы без M. Метод надо явно включить в ограничение.','type N int;func(n N)M()int{return int(n)};func Call[T ~int](x T)int{return x.M()}');
q('Пересечение базового типа и метода','fmt.Println(Call(N(8)))','8',['0','panic','Не компилируется'],'Ограничение требует одновременно базовый int и метод M. Определённый N удовлетворяет обоим требованиям.','type N int;func(n N)M()int{return int(n)};func Call[T interface{~int;M()int}](x T)int{return x.M()}');
bad('Утверждение типа на параметре','fmt.Println(IsInt(1))','cannot use type assertion',['true','false','panic'],'Параметр T — не интерфейсное выражение для type assertion, даже при ограничении any. Нужна упаковка any(x).','func IsInt[T any](x T)bool{_,ok:=x.(int);return ok}');
q('Упаковка параметра сохраняет определённый тип','fmt.Println(IsInt(N(1)),IsInt(1))','false true',['true true','false false','Не компилируется'],'После any(x) проверяется точный динамический тип. N с базовым int не является самим int.','type N int;func IsInt[T any](x T)bool{_,ok:=any(x).(int);return ok}');
q('Метод инстанцированного контейнера','b:=Box[string]{"go"};fmt.Printf("%T %v",b.Get(),b.Get())','string go',['main.Box[string] go','interface {} go','Не компилируется'],'Параметр в объявлении получателя связывается с аргументом инстанциации. Get возвращает T=string без интерфейсной упаковки.','type Box[T any]struct{V T};func(b Box[T])Get()T{return b.V}');
bad('Инстанциации контейнера инвариантны','var x Box[any]=Box[int]{1};fmt.Println(x)','cannot use',['{1}','{<nil>}','panic'],'Box[int] и Box[any] — разные инстанцированные типы. Присваиваемость int к any не переносится автоматически на контейнеры.','type Box[T any]struct{V T}');
section('Экзамен · Рефлексия и динамические границы');
q('TypeOf nil и тип указателя','var p *int;fmt.Println(reflect.TypeOf(nil)==nil,reflect.TypeOf(p).Kind())','true ptr',['true invalid','false ptr','panic'],'У nil-интерфейса TypeOf возвращает nil. У типизированного nil-указателя есть динамический тип *int с Kind ptr.','','fmt,reflect');
q('TypeFor получает тип интерфейса','t:=reflect.TypeFor[error]();fmt.Println(t.Kind(),t.NumMethod())','interface 1',['ptr 1','invalid 0','panic'],'TypeFor получает статический тип аргумента, даже если его нулевое значение было бы nil-интерфейсом. error содержит один метод Error.','','fmt,reflect');
q('Elem интерфейса раскрывает динамический тип','var x any=7;v:=reflect.ValueOf(&x).Elem();fmt.Println(v.Kind(),v.Elem().Kind(),v.CanSet(),v.Elem().CanSet())','interface int true false',['int int true true','interface int false false','panic'],'Адресуемая ячейка интерфейса доступна для Set. Её динамическое значение int извлекается как неадресуемая копия.','','fmt,reflect');
q('Замена содержимого интерфейса через Set','var x any=7;reflect.ValueOf(&x).Elem().Set(reflect.ValueOf("go"));fmt.Printf("%T %v",x,x)','string go',['int 7','interface {} go','panic'],'Строка присваиваема any, а ячейка интерфейса адресуема. Set заменяет и динамический тип, и динамическое значение.','','fmt,reflect');
q('SetInt сохраняет определённый тип','x:=N(3);v:=reflect.ValueOf(&x).Elem();v.SetInt(8);fmt.Printf("%T %v",x,x)','main.N 8',['int 8','main.N 3','panic'],'SetInt работает по Kind и записывает в исходную ячейку N. Тип переменной не превращается в int.','type N int','fmt,reflect');
q('Set не выполняет числовое преобразование','defer func(){fmt.Println(recover()!=nil)}();x:=N(3);reflect.ValueOf(&x).Elem().Set(reflect.ValueOf(8))','true',['false','8','Не компилируется'],'Set требует присваиваемости; типизированный int не присваивается определённому N автоматически. Для этого нужен Convert к типу N.','type N int','fmt,reflect');
q('Convert перед Set','x:=N(3);v:=reflect.ValueOf(&x).Elem();v.Set(reflect.ValueOf(8).Convert(v.Type()));fmt.Println(x)','8',['3','0','panic'],'Convert создаёт значение точного типа N, после чего Set допустим. В отличие от SetInt этот путь явно проверяет преобразование типа.','type N int','fmt,reflect');
q('Неэкспортируемое поле читается как число','v:=reflect.ValueOf(struct{x int}{7}).Field(0);fmt.Println(v.Int(),v.CanInterface())','7 false',['7 true','0 false','panic'],'Специализированный Int позволяет прочитать числовое поле. Interface запрещён для неэкспортируемого поля даже в том же пакете.','','fmt,reflect');
q('Interface у закрытого поля','defer func(){fmt.Println(recover()!=nil)}();v:=reflect.ValueOf(struct{x int}{7}).Field(0);fmt.Println(v.Interface())','true',['7','false','Не компилируется'],'Value.Interface паникует для значения, полученного из неэкспортируемого поля. Видимость не обходится за счёт нахождения вызова в main.','','fmt,reflect');
q('Невалидное значение отсутствующего ключа','v:=reflect.ValueOf(map[string]int{}).MapIndex(reflect.ValueOf("x"));fmt.Println(v.IsValid(),v.Kind())','false invalid',['true int','true invalid','panic'],'Отсутствующий ключ возвращает zero Value, а не отражённый нулевой int. Для него безопасны IsValid и Kind.','','fmt,reflect');
q('Удаление ключа невалидным Value','m:=map[string]int{"x":7};reflect.ValueOf(m).SetMapIndex(reflect.ValueOf("x"),reflect.Value{});fmt.Println(len(m))','0',['1','7','panic'],'В SetMapIndex невалидный элемент означает удаление ключа. Это отличается от записи отражённого нуля типа int.','','fmt,reflect');
q('Элемент map не адресуем','m:=map[string]int{"x":7};v:=reflect.ValueOf(m).MapIndex(reflect.ValueOf("x"));fmt.Println(v.CanAddr(),v.CanSet())','false false',['true true','false true','panic'],'MapIndex возвращает копию значения. Для изменения карты используется SetMapIndex, а не изменение полученного Value.','','fmt,reflect');
q('Элемент среза доступен без адреса заголовка','s:=[]int{1};v:=reflect.ValueOf(s);v.Index(0).SetInt(9);fmt.Println(v.CanSet(),s)','false [9]',['true [9]','false [1]','panic'],'Заголовок из ValueOf не устанавливаем, но его элементы адресуемы и ссылаются на общий массив среза.','','fmt,reflect');
q('Массив и указатель на него в reflect','a:=[1]int{1};v:=reflect.ValueOf(a);p:=reflect.ValueOf(&a).Elem();p.Index(0).SetInt(9);fmt.Println(v.Index(0).Int(),p.Index(0).Int(),v.Index(0).CanSet())','1 9 false',['9 9 true','1 1 false','panic'],'ValueOf(a) содержит независимую неадресуемую копию массива. Elem указателя раскрывает исходный массив и позволяет менять его элементы.','','fmt,reflect');
q('CanConvert учитывает длину среза','v:=reflect.ValueOf([]int{1});t:=reflect.TypeOf((*[2]int)(nil));fmt.Println(v.Type().ConvertibleTo(t),v.CanConvert(t))','true false',['true true','false false','panic'],'Преобразование []int в *[2]int допустимо по типам, но для конкретного среза длины 1 вызвало бы панику. CanConvert проверяет и это условие.','','fmt,reflect');
q('Reflect Call не подставляет преобразование','defer func(){fmt.Println(recover()!=nil)}();f:=reflect.ValueOf(func(x int64){});f.Call([]reflect.Value{reflect.ValueOf(3)})','true',['false','3','Не компилируется'],'Call требует аргументы присваиваемых типов. Отражённое значение 3 уже имеет тип int и не преобразуется в int64 автоматически.','','fmt,reflect');
q('CallSlice разворачивает последний срез','f:=reflect.ValueOf(func(prefix string,xs ...int)string{return fmt.Sprint(prefix,len(xs))});r:=f.CallSlice([]reflect.Value{reflect.ValueOf("n="),reflect.ValueOf([]int{2,4,6})});fmt.Println(r[0].String())','n=3',['n=1','n=0','panic'],'CallSlice соответствует вызову с xs...: последним аргументом передаётся срез точного variadic-типа, который раскрывается в три элемента.','','fmt,reflect');
q('MakeFunc должен вернуть значения нужного типа','defer func(){fmt.Println(recover()!=nil)}();t:=reflect.TypeOf(func()int{return 0});v:=reflect.MakeFunc(t,func([]reflect.Value)[]reflect.Value{return []reflect.Value{reflect.ValueOf(int64(3))}});v.Call(nil)','true',['3','false','Не компилируется'],'Сигнатура MakeFunc обещает int, callback возвращает int64. Проверка результатов происходит при динамическом вызове и вызывает панику.','','fmt,reflect');
q('NumMethod различает значение и указатель','fmt.Println(reflect.TypeOf(N{}).NumMethod(),reflect.TypeOf(&N{}).NumMethod())','1 2',['2 2','1 1','0 2'],'Методы с получателем N входят в оба множества. Указательный метод входит только в *N; оба экспортированы и видны reflect.','type N struct{};func(N)A(){};func(*N)B(){}','fmt,reflect');
q('Comparable проверяет содержимое интерфейсного поля','v:=reflect.ValueOf(struct{X any}{[]int{1}});fmt.Println(v.Type().Comparable(),v.Comparable())','true false',['true true','false false','panic'],'Структура с полем any сравнима как тип. Value.Comparable учитывает конкретный динамический срез, из-за которого сравнение значения запаниковало бы.','','fmt,reflect');
section('Экзамен · JSON, ошибки и стандартные контракты');
q('JSON в any выбирает float64','var x any;json.Unmarshal([]byte(`{"n":7}`),&x);fmt.Printf("%T",x.(map[string]any)["n"])','float64',['int','json.Number','Не компилируется'],'Без UseNumber числа при декодировании в any становятся float64, а объект — map[string]any.','','fmt,encoding/json');
q('UseNumber сохраняет текст числа','d:=json.NewDecoder(strings.NewReader(`1234567890123456789`));d.UseNumber();var x any;d.Decode(&x);fmt.Printf("%T %v",x,x)','json.Number 1234567890123456789',['float64 1234567890123456789','int64 1234567890123456789','panic'],'UseNumber выбирает json.Number для чисел в интерфейсах; значение хранит исходную десятичную запись без округления float64.','','fmt,encoding/json,strings');
q('Null не обнуляет обычный int','x:=7;err:=json.Unmarshal([]byte(`null`),&x);fmt.Println(x,err==nil)','7 true',['0 true','7 false','panic'],'Декодирование null в обычное числовое значение ничего не меняет и не считается ошибкой. Для указателя null устанавливает nil.','','fmt,encoding/json');
q('Null обнуляет указатель','x:=7;p:=&x;json.Unmarshal([]byte(`null`),&p);fmt.Println(p==nil,x)','true 7',['false 7','true 0','panic'],'Декодер меняет ячейку указателя p на nil. Ранее адресуемая переменная x остаётся равной 7.','','fmt,encoding/json');
q('Декодирование map сохраняет отсутствующие ключи','m:=map[string]int{"old":1,"x":2};json.Unmarshal([]byte(`{"x":9}`),&m);fmt.Println(m["old"],m["x"],len(m))','1 9 2',['0 9 1','1 2 2','panic'],'Ненулевая карта переиспользуется: перечисленные ключи обновляются, отсутствующие в JSON старые ключи сохраняются.','','fmt,encoding/json');
q('Повторное поле JSON заменяет скаляр','var x struct{N int};json.Unmarshal([]byte(`{"N":1,"N":8}`),&x);fmt.Println(x.N)','8',['1','0','Ошибка декодирования'],'Поля объекта обрабатываются по порядку. Для скалярного int более позднее значение одноимённого поля заменяет раннее.','','fmt,encoding/json');
q('OmitEmpty у nil-указателя и указателя на ноль','z:=0;b,_:=json.Marshal(struct{A *int `json:"a,omitempty"`;B *int `json:"b,omitempty"`}{nil,&z});fmt.Println(string(b))','{"b":0}',['{}','{"a":null,"b":0}','{"a":null}'],'omitempty проверяет сам указатель: nil опускается, ненулевой указатель включается независимо от нулевого значения по адресу.','','fmt,encoding/json');
q('OmitEmpty у интерфейса с nil-указателем','var p *int;b,_:=json.Marshal(struct{X any `json:"x,omitempty"`}{p});fmt.Println(string(b))','{"x":null}',['{}','{"x":0}','Ошибка Marshal'],'Интерфейс ненулевой, поэтому поле не опускается. Его динамический nil-указатель сериализуется как null.','','fmt,encoding/json');
q('Nil и пустой срез в JSON','a,_:=json.Marshal([]int(nil));b,_:=json.Marshal([]int{});fmt.Println(string(a),string(b))','null []',['[] []','null null','{} []'],'Nil-срез кодируется как null, ненулевой срез длины ноль — как пустой массив. Равная длина не означает одинаковую сериализацию.','','fmt,encoding/json');
q('Байтовый срез кодируется особо','b,_:=json.Marshal([]byte{71,111});fmt.Println(string(b))','"R28="',['[71,111]','"Go"','Ошибка Marshal'],'encoding/json обрабатывает []byte как двоичные данные и кодирует строкой base64; это не общий путь сериализации среза чисел.','','fmt,encoding/json');
q('Тег string требует строковое число','var x struct{N int `json:"n,string"`};err:=json.Unmarshal([]byte(`{"n":12}`),&x);fmt.Println(err!=nil,x.N)','true 0',['false 12','false 0','panic'],'Опция string ожидает JSON-строку, внутри которой записано число. Обычный числовой JSON-токен для такого поля отвергается.','','fmt,encoding/json');
q('Неизвестное поле по умолчанию','var x struct{N int};err:=json.Unmarshal([]byte(`{"N":4,"extra":8}`),&x);fmt.Println(err==nil,x.N)','true 4',['false 0','false 4','panic'],'Unmarshal по умолчанию игнорирует неизвестные поля структуры. Строгий режим включается отдельно у Decoder.','','fmt,encoding/json');
q('DisallowUnknownFields сохраняет уже прочитанное','d:=json.NewDecoder(strings.NewReader(`{"N":4,"extra":8}`));d.DisallowUnknownFields();var x struct{N int};err:=d.Decode(&x);fmt.Println(err!=nil,x.N)','true 4',['true 0','false 4','panic'],'Строгий режим возвращает ошибку неизвестного поля, но не откатывает уже выполненные изменения структуры.','','fmt,encoding/json,strings');
q('Проценты v и w в цепочке ошибок','base:=errors.New("x");a:=fmt.Errorf("wrap: %v",base);b:=fmt.Errorf("wrap: %w",base);fmt.Println(errors.Is(a,base),errors.Is(b,base))','false true',['true true','false false','Не компилируется'],'%v добавляет лишь текст. %w создаёт цепочку Unwrap, которую обходит errors.Is.','','fmt,errors');
q('Одинаковый текст не делает ошибки равными','a:=errors.New("x");b:=errors.New("x");fmt.Println(a==b,errors.Is(a,b))','false false',['true true','false true','panic'],'Каждый errors.New создаёт отдельную ошибку. Без пользовательского Is сравнение основано на идентичности, а не на строке Error().','','fmt,errors');
q('Join пропускает nil и сохраняет обе причины','a:=errors.New("a");b:=errors.New("b");e:=errors.Join(nil,a,b);fmt.Println(errors.Is(e,a),errors.Is(e,b),errors.Join(nil,nil)==nil)','true true true',['true false true','false true false','panic'],'Join включает все ненулевые причины в дерево. Если таких причин нет, возвращается nil; Is обходит обе ветви.','','fmt,errors');
q('Unwrap не раскрывает множественную ошибку','e:=errors.Join(errors.New("a"),errors.New("b"));fmt.Println(errors.Unwrap(e)==nil)','true',['false','panic','Не компилируется'],'errors.Unwrap работает только с Unwrap()error. Join предоставляет Unwrap()[]error; для обхода его дерева нужны Is или As.','','fmt,errors');
q('As извлекает указатель конкретной ошибки','var target *E;err:=fmt.Errorf("wrap: %w",&E{7});ok:=errors.As(err,&target);fmt.Println(ok,target.Code)','true 7',['false 0','true 0','panic'],'As получает адрес переменной *E, то есть **E, и записывает в неё найденную конкретную ошибку из цепочки.','type E struct{Code int};func(e *E)Error()string{return "E"}','fmt,errors');
q('As с nil-целью паникует','defer func(){fmt.Println(recover()!=nil)}();var target *E;errors.As(&E{},target)','true',['false','<nil>','Не компилируется'],'Цель As должна быть ненулевым указателем на ячейку результата. Нулевой *E не является адресом переменной target; нужен &target.','type E struct{};func(*E)Error()string{return "E"}','fmt,errors');
q('Nil-ошибка внутри Join остаётся типизированной','var p *E;var e error=p;j:=errors.Join(e);fmt.Println(j==nil,errors.Is(j,e))','false true',['true false','false false','panic'],'Типизированный nil внутри error не равен nil и включается в Join. Is находит тот же динамический тип и nil-указатель.','type E struct{};func(*E)Error()string{return "E"}','fmt,errors');
section('Экзамен · Адаптеры потоков и функций');
q('ReadFull отличает короткий поток','b:=make([]byte,4);n,e:=io.ReadFull(strings.NewReader("go"),b);fmt.Println(n,e==io.ErrUnexpectedEOF,string(b[:n]))','2 true go',['2 false go','0 true','4 false go'],'ReadFull требует заполнить весь буфер. Если данные уже получены, но поток закончился раньше, возвращается ErrUnexpectedEOF.','','fmt,io,strings');
q('ReadFull из пустого потока','n,e:=io.ReadFull(strings.NewReader(""),make([]byte,2));fmt.Println(n,e==io.EOF,e==io.ErrUnexpectedEOF)','0 true false',['0 false true','2 false false','panic'],'Если до конца потока не прочитан ни один байт, ReadFull возвращает EOF. ErrUnexpectedEOF означает частичное заполнение.','','fmt,io,strings');
q('ReadAll потребляет данные вместе с EOF','b,e:=io.ReadAll(R{});fmt.Println(string(b),e==nil)','ok true',['ok false',' true','panic'],'Reader может вернуть байты и EOF одним вызовом. ReadAll сохраняет эти байты и считает EOF нормальным завершением.','type R struct{};func(R)Read(p []byte)(int,error){return copy(p,"ok"),io.EOF}','fmt,io');
q('LimitReader оставляет хвост исходного потока','r:=strings.NewReader("abcdef");a,_:=io.ReadAll(io.LimitReader(r,3));b,_:=io.ReadAll(r);fmt.Println(string(a),string(b))','abc def',['abc abcdef','abcdef','panic'],'Адаптер читает не более трёх байтов из общего Reader. Он не создаёт независимую копию состояния исходного потока.','','fmt,io,strings');
q('MultiReader читает источники последовательно','r:=io.MultiReader(strings.NewReader("a"),strings.NewReader(""),strings.NewReader("bc"));b,e:=io.ReadAll(r);fmt.Println(string(b),e==nil)','abc true',['a true','abc false','panic'],'MultiReader переходит к следующему Reader после EOF, включая пустые источники; итоговый EOF ReadAll не возвращает как ошибку.','','fmt,io,strings');
q('TeeReader пишет только прочитанное','var b bytes.Buffer;r:=io.TeeReader(strings.NewReader("abcd"),&b);p:=make([]byte,2);io.ReadFull(r,p);fmt.Println(string(p),b.String())','ab ab',['ab abcd','abcd abcd','panic'],'TeeReader копирует данные в Writer по мере чтения. Создание адаптера само по себе не потребляет оставшиеся байты.','','fmt,io,strings,bytes');
q('MultiWriter останавливается на ошибке','var b bytes.Buffer;n,e:=io.MultiWriter(W{},&b).Write([]byte("go"));fmt.Println(n,e!=nil,b.Len())','0 true 0',['2 true 2','0 true 2','2 false 2'],'MultiWriter вызывает Writer по порядку и прекращает запись после первой ошибки. Второй буфер не получает данных.','type W struct{};func(W)Write([]byte)(int,error){return 0,errors.New("stop")}','fmt,io,bytes,errors');
q('Copy замечает короткую запись без ошибки','n,e:=io.Copy(W{},strings.NewReader("abcd"));fmt.Println(n,e==io.ErrShortWrite)','1 true',['4 false','1 false','0 true'],'Writer нарушает контракт, сообщая короткую запись без ошибки. Copy либо оптимизированный WriterTo источника преобразует это в ErrShortWrite.','type W struct{};func(W)Write([]byte)(int,error){return 1,nil}','fmt,io,strings');
q('NopCloser не сбрасывает Reader при Close','r:=io.NopCloser(strings.NewReader("go"));r.Close();b,e:=io.ReadAll(r);fmt.Println(string(b),e==nil)','go true',[' true','go false','panic'],'Close у NopCloser ничего не делает. Сам адаптер не запрещает последующие чтения и не закрывает обёрнутый Reader.','','fmt,io,strings');
q('WriterTo имеет приоритет в Copy','s:=S{};d:=D{};n,_:=io.Copy(d,s);fmt.Println(n)','source\n7',['destination\n9','read\n0','panic'],'Copy сначала проверяет WriterTo у источника и только затем ReaderFrom у назначения. Вызывается источник, обходя обычный Read.','type S struct{};func(S)Read([]byte)(int,error){fmt.Println("read");return 0,io.EOF};func(S)WriteTo(io.Writer)(int64,error){fmt.Println("source");return 7,nil};type D struct{};func(D)Write(p []byte)(int,error){return len(p),nil};func(D)ReadFrom(io.Reader)(int64,error){fmt.Println("destination");return 9,nil}','fmt,io');
q('Обёртка Reader скрывает оптимизацию','s:=struct{io.Reader}{S{}};n,_:=io.Copy(D{},s);fmt.Println(n)','destination\n9',['source\n7','read\n0','Не компилируется'],'Обёртка продвигает только методы статического io.Reader. WriterTo динамического S не продвигается, поэтому Copy выбирает ReaderFrom назначения.','type S struct{};func(S)Read([]byte)(int,error){fmt.Println("read");return 0,io.EOF};func(S)WriteTo(io.Writer)(int64,error){fmt.Println("source");return 7,nil};type D struct{};func(D)Write(p []byte)(int,error){return len(p),nil};func(D)ReadFrom(io.Reader)(int64,error){fmt.Println("destination");return 9,nil}','fmt,io');
q('ReaderFunc хранит состояние замыкания','n:=0;r:=RF(func(p []byte)(int,error){if n==2{return 0,io.EOF};p[0]=byte(65+n);n++;return 1,nil});b,_:=io.ReadAll(r);fmt.Println(string(b),n)','AB 2',['AA 1','AB 0','panic'],'Функциональный адаптер вызывает одно замыкание с общей переменной n. Каждый Read продолжает состояние предыдущего.','type RF func([]byte)(int,error);func(f RF)Read(p []byte)(int,error){return f(p)}','fmt,io');
q('Декоратор с value receiver теряет счётчик','c:=Count{Reader:strings.NewReader("abc")};io.ReadAll(c);fmt.Println(c.N)','0',['3','1','Не компилируется'],'Метод Read изменяет копию Count. Вложенный Reader содержит общий указатель и продвигается, но поле N исходной структуры не меняется.','type Count struct{io.Reader;N int};func(c Count)Read(p []byte)(int,error){n,e:=c.Reader.Read(p);c.N+=n;return n,e}','fmt,io,strings');
q('Указательный декоратор накапливает байты','c:=&Count{Reader:strings.NewReader("abc")};io.ReadAll(c);fmt.Println(c.N)','3',['0','1','panic'],'Указательный получатель обновляет единственный Count. Встраивание io.Reader не предоставляет WriterTo, поэтому чтение проходит через Count.Read.','type Count struct{io.Reader;N int};func(c *Count)Read(p []byte)(int,error){n,e:=c.Reader.Read(p);c.N+=n;return n,e}','fmt,io,strings');
q('Адаптер ошибки сохраняет частичный результат','f:=Adapt(func()(int,error){return 7,errors.New("x")});v,e:=f();fmt.Println(v,e!=nil)','7 true',['0 true','7 false','panic'],'Обёртка изменяет контекст ошибки через %w, но возвращает полученное значение. Наличие ошибки само по себе не обнуляет результат.','func Adapt(f func()(int,error))func()(int,error){return func()(int,error){v,e:=f();if e!=nil{return v,fmt.Errorf("adapt: %w",e)};return v,nil}}','fmt,errors');
q('Фабрика callback вызывается один раз','n:=0;makeF:=func()func(int)int{n++;return func(x int)int{return x+n}};f:=Twice(makeF());fmt.Println(f(1),n)','3 1',['4 2','2 1','panic'],'Twice получает уже созданную функцию и вызывает её дважды; фабрика makeF исполняется один раз при передаче аргумента.','func Twice(f func(int)int)func(int)int{return func(x int)int{return f(f(x))}}');
q('Срез callbacks меняется после построения цепочки','fs:=[]func(int)int{func(x int)int{return x+1}};f:=Chain(fs);fs[0]=func(x int)int{return x*10};fmt.Println(f(2))','20',['3','2','panic'],'Chain сохраняет заголовок среза, а не копию массива функций. Замена fs[0] видна при последующем исполнении цепочки.','func Chain(fs []func(int)int)func(int)int{return func(x int)int{for _,f:=range fs{x=f(x)};return x}}');
q('Снимок callbacks фиксирует состав цепочки','fs:=[]func(int)int{func(x int)int{return x+1}};f:=Chain(fs);fs[0]=func(x int)int{return x*10};fmt.Println(f(2))','3',['20','2','panic'],'Копирование элементов среза фиксирует сами функции. Замена элемента исходного массива не меняет копию, используемую цепочкой.','func Chain(fs []func(int)int)func(int)int{fs=append([]func(int)int(nil),fs...);return func(x int)int{for _,f:=range fs{x=f(x)};return x}}');
q('Копия функции не копирует захваченное состояние','n:=0;f:=func()int{n++;return n};g:=f;fmt.Println(f(),g(),f())','1 2 3',['1 1 2','1 2 2','Не компилируется'],'Обе функциональные переменные ссылаются на замыкание с одной захваченной n. Присваивание функции не клонирует её окружение.');
q('Частичное применение фиксирует скаляр','k:=2;f:=Bind(func(a,b int)int{return a*b},k);k=9;fmt.Println(f(3),k)','6 9',['27 9','6 2','Не компилируется'],'В Bind передаётся копия текущего k=2. Замыкание захватывает параметр a фабрики, а не внешнюю переменную k.','func Bind(f func(int,int)int,a int)func(int)int{return func(b int)int{return f(a,b)}}');
section('Экзамен · Каналы, синхронизация и отмена');
q('Nil-канал отключает ветку select','var ch chan int;select{case ch<-1:fmt.Println("sent");default:fmt.Println("default")}','default',['sent','deadlock','panic'],'Отправка в nil-канал никогда не готова. Наличие default позволяет select завершиться без блокировки.');
q('Значение отправки вычисляется перед выбором default','var ch chan int;n:=0;f:=func()int{n++;return 7};select{case ch<-f():default:};fmt.Println(n)','1',['0','7','deadlock'],'При входе в select вычисляются канал и выражение отправляемого значения каждой ветки. Это происходит даже для nil-канала и невыбранной ветки.');
q('Левая часть получения вычисляется только при выборе','ch:=make(chan int,1);ch<-4;n:=0;idx:=func()int{n++;return 0};a:=[]int{0};select{case a[idx()]=<-ch:default:};fmt.Println(a,n)','[4] 1',['[0] 1','[4] 0','panic'],'Выражения левой части присваивания при получении вычисляются после выбора соответствующей ветки. Готовое чтение выбирается вместо default.');
q('Невыбранное получение не вычисляет индекс','var ch chan int;n:=0;idx:=func()int{n++;return 0};a:=[]int{0};select{case a[idx()]=<-ch:default:};fmt.Println(a,n)','[0] 0',['[0] 1','[1] 1','deadlock'],'Nil-канал отключает получение, выбирается default. Индекс левой части невыбранной ветки не вычисляется.');
q('Отправка в закрытый канал побеждает default паникой','defer func(){fmt.Println(recover()!=nil)}();ch:=make(chan int);close(ch);select{case ch<-1:fmt.Println("sent");default:fmt.Println("default")}','true',['default','sent','deadlock'],'Закрытый канал не превращает отправку в блокирующую операцию. Выбранная отправка паникует; default не служит проверкой закрытия.');
q('Два чтения закрытого канала в range','ch:=make(chan int,2);ch<-2;ch<-5;close(ch);sum:=0;for x:=range ch{sum+=x};fmt.Println(sum)','7',['0','2','deadlock'],'Range извлекает накопленные элементы, затем заканчивается на закрытом пустом канале. Нулевые значения после закрытия не добавляются бесконечно.');
q('Закрытие копии канала видно оригиналу','a:=make(chan int);b:=a;close(b);_,ok:=<-a;fmt.Println(ok,a==b)','false true',['true true','false false','deadlock'],'Канальное значение ссылается на один объект канала. Присваивание не создаёт отдельную очередь или отдельное состояние закрытия.');
bad('Принимающий канал нельзя закрыть','ch:=make(chan int);var r <-chan int=ch;close(r);fmt.Println("done")','cannot close receive-only channel',['done','panic','deadlock'],'Close разрешён для двунаправленного или отправляющего канала. Направление статического типа r ограничивает операцию, несмотря на исходный ch.');
q('Отправляющий канал можно закрыть','ch:=make(chan int);var s chan<- int=ch;close(s);_,ok:=<-ch;fmt.Println(ok)','false',['true','panic','Не компилируется'],'Право отправки включает право закрытия. Получение через сохранённый двунаправленный ch обнаруживает закрытый канал.');
q('Close синхронизирует запись перед ним','done:=make(chan struct{});x:=0;go func(){x=7;close(done)}();<-done;fmt.Println(x)','7',['0','Гонка данных','deadlock'],'Закрытие канала синхронизировано с получением, которое обнаруживает закрытие. Запись x до close видна после получения, гонки здесь нет.');
q('Буферизированная отправка передаёт видимость','ch:=make(chan int,1);x:=0;go func(){x=9;ch<-1}();<-ch;fmt.Println(x)','9',['0','Гонка данных','deadlock'],'Отправка синхронизирована с соответствующим получением и публикует предшествующую запись x. Буферизация этого свойства не отменяет.');
q('WaitGroup ждёт изменения callback','var wg sync.WaitGroup;x:=0;wg.Add(1);go func(){defer wg.Done();x=5}();wg.Wait();fmt.Println(x)','5',['0','Гонка данных','deadlock'],'Add выполнен до старта горутины. Done синхронизируется с разблокированным Wait, так что последующее чтение x безопасно.','','fmt,sync');
q('Once игнорирует последующие функции','var once sync.Once;n:=0;once.Do(func(){n+=2});once.Do(func(){n+=10});fmt.Println(n)','2',['12','10','0'],'Once связан с объектом синхронизации, а не с идентичностью callback. Второй callback не выполняется.','','fmt,sync');
q('Паника помечает Once использованным','var once sync.Once;func(){defer func(){recover()}();once.Do(func(){panic("x")})}();n:=0;once.Do(func(){n++});fmt.Println(n)','0',['1','panic','deadlock'],'Once считает первый Do завершённым даже при панике функции. Перехват паники снаружи не сбрасывает состояние Once.','','fmt,sync');
q('OnceValue кэширует нулевой результат','n:=0;f:=sync.OnceValue(func()int{n++;return 0});fmt.Println(f(),f(),n)','0 0 1',['0 0 2','1 1 1','Не компилируется'],'OnceValue хранит факт исполнения отдельно от результата. Нулевой int не означает, что вычисление нужно повторить.','','fmt,sync');
q('CancelCause сохраняет первую причину','ctx,cancel:=context.WithCancelCause(context.Background());a:=errors.New("a");cancel(a);cancel(errors.New("b"));fmt.Println(context.Cause(ctx)==a,ctx.Err()==context.Canceled)','true true',['false true','true false','panic'],'Первая отмена фиксирует причину; повторная её не заменяет. Err сообщает стандартную категорию, Cause — конкретную причину.','','fmt,context,errors');
q('WithoutCancel убирает сигнал, но сохраняет Value','base:=context.WithValue(context.Background(),key{},7);ctx,cancel:=context.WithCancel(base);safe:=context.WithoutCancel(ctx);cancel();fmt.Println(safe.Done()==nil,safe.Err()==nil,safe.Value(key{}))','true true 7',['false false 7','true true <nil>','panic'],'WithoutCancel не наследует отмену и дедлайн родителя, но передаёт поиск значений к нему. Done такого контекста равен nil.','type key struct{}','fmt,context');
q('Разные типы ключей контекста','ctx:=context.WithValue(context.Background(),K("id"),7);fmt.Println(ctx.Value("id")==nil,ctx.Value(K("id")))','true 7',['false 7','true <nil>','panic'],'Ключи сравниваются как интерфейсные значения. string и определённый K имеют разные динамические типы даже при одинаковой строке.','type K string','fmt,context');
q('Несравнимый ключ контекста','defer func(){fmt.Println(recover()!=nil)}();context.WithValue(context.Background(),[]int{1},7)','true',['false','7','Не компилируется'],'WithValue требует сравнимый ключ и проверяет его во время исполнения. Срез допустим как any, но не как ключ контекста.','','fmt,context');
q('Atomic Swap возвращает прежнее значение','var n atomic.Int64;n.Store(4);old:=n.Swap(9);ok:=n.CompareAndSwap(4,12);fmt.Println(old,ok,n.Load())','4 false 9',['9 true 12','4 true 12','9 false 4'],'Swap возвращает старое значение 4, сохраняя 9. CompareAndSwap ожидает 4 и поэтому не меняет текущее значение.','','fmt,sync/atomic');
section('Экзамен · Коллекции, память и копирование');
q('Полное выражение среза отделяет append','a:=[]int{1,2,3};s:=a[:1:1];s=append(s,9);s[0]=7;fmt.Println(a,s)','[1 2 3] [7 9]',['[7 9 3] [7 9]','[7 2 3] [7 9]','panic'],'Ограничение cap до 1 вынуждает append выделить новый массив. Все дальнейшие изменения s происходят уже в нём.');
q('Append двух перекрывающихся срезов','a:=[]int{1,2,3,4};s:=append(a[:1],a[1:3]...);fmt.Println(a,s)','[1 2 3 4] [1 2 3]',['[1 1 1 4] [1 1 1]','[1 2 3 4] [1 2 3 4]','panic'],'Append корректно работает с перекрывающимися источником и назначением. Здесь копируются те же 2 и 3 в исходные позиции; длина s равна 3.');
q('Две перекрывающиеся операции Copy','a:=[]int{1,2,3,4};n:=copy(a[1:],a);m:=copy(a,a[2:]);fmt.Println(n,m,a)','3 2 [2 3 2 3]',['3 2 [1 1 1 1]','3 2 [3 4 2 3]','panic'],'Первая операция оставляет [1 1 2 3]; вторая копирует её текущий хвост [2 3] в начало. Каждая операция корректно обрабатывает перекрытие.');
q('Срез массива внутри копии структуры','a:=S{A:[2]int{1,2}};b:=a;s:=b.A[:];s[0]=9;fmt.Println(a.A,b.A)','[1 2] [9 2]',['[9 2] [9 2]','[1 2] [1 2]','Не компилируется'],'Массив встроен в структуру по значению и копируется вместе с ней. Срез адресуемого поля b.A ссылается только на массив копии b.','type S struct{A [2]int}');
q('Копия структуры со срезом разделяет элементы','a:=S{A:[]int{1,2}};b:=a;b.A[0]=9;b.A=b.A[:1];fmt.Println(a.A,b.A)','[9 2] [9]',['[1 2] [9]','[9] [9]','panic'],'Копируются заголовки срезов, поэтому длины независимы, а массив общий. Изменение элемента видно через a, уменьшение длины b — нет.','type S struct{A []int}');
q('Range массива читает снимок','a:=[3]int{1,2,3};sum:=0;for i,v:=range a{if i==0{a[1]=9};sum+=v};fmt.Println(sum,a)','6 [1 9 3]',['13 [1 9 3]','6 [1 2 3]','panic'],'Выражение массива для range копируется. v берётся из снимка, тогда как явная запись a[1] меняет исходный массив.');
q('Range указателя на массив видит запись','a:=[3]int{1,2,3};sum:=0;for i,v:=range &a{if i==0{a[1]=9};sum+=v};fmt.Println(sum,a)','13 [1 9 3]',['6 [1 9 3]','6 [1 2 3]','Не компилируется'],'Range по указателю не копирует массив. Значение очередного элемента читается из того же массива, поэтому вторая итерация видит 9.');
q('Range среза фиксирует длину','s:=make([]int,2,4);s[0]=1;s[1]=2;sum:=0;for _,v:=range s{sum+=v;s=append(s,9)};fmt.Println(sum,len(s))','3 4',['21 4','3 2','Бесконечный цикл'],'Range сохраняет исходный заголовок с длиной 2. Append меняет переменную s, но не число итераций начатого цикла.');
q('Clone среза копирует только верхний уровень','a:=[][]int{{1}};b:=slices.Clone(a);b[0][0]=7;b=append(b,[]int{8});fmt.Println(a,b)','[[7]] [[7] [8]]',['[[1]] [[7] [8]]','[[7] [8]] [[7] [8]]','panic'],'Clone копирует элементы внешнего среза; ими являются заголовки внутренних срезов. Внутренний массив остаётся общим, длина внешнего a не меняется.','','fmt,slices');
q('Clone сохраняет nil-срез','var a []int;b:=slices.Clone(a);fmt.Println(b==nil,len(b))','true 0',['false 0','true 1','panic'],'slices.Clone сохраняет nilness исходного среза. Пустота сама по себе не требует выделения нового ненулевого среза.','','fmt,slices');
q('Delete обнуляет освобождённый хвост','a:=[]int{1,2,3,4};b:=slices.Delete(a,1,3);fmt.Println(a,b)','[1 4 0 0] [1 4]',['[1 4 3 4] [1 4]','[1 2 3 4] [1 4]','panic'],'В Go 1.23 Delete сдвигает хвост и очищает ставшие лишними элементы. Старый заголовок a сохраняет длину 4 и показывает обнулённые позиции.','','fmt,slices');
q('Compact удаляет только соседние повторы','a:=[]int{1,1,2,1};b:=slices.Compact(a);fmt.Println(b,a)','[1 2 1] [1 2 1 0]',['[1 2] [1 2 0 0]','[1 2 1] [1 2 1 1]','panic'],'Compact объединяет серии равных соседей, а не все одинаковые значения. Освободившийся хвост очищается в Go 1.23.','','fmt,slices');
q('Map Clone оставляет общие указатели','x:=1;a:=map[string]*int{"x":&x};b:=maps.Clone(a);*b["x"]=7;delete(b,"x");fmt.Println(*a["x"],len(a),len(b))','7 1 0',['1 1 0','7 0 0','panic'],'Карта клонируется отдельно, но её указательные значения копируются поверхностно. Запись по указателю общая, удаление ключа — локально для b.','','fmt,maps');
q('Nil map допускает delete и clear','var m map[string]int;delete(m,"x");clear(m);fmt.Println(m==nil,len(m))','true 0',['false 0','true 1','panic'],'Удаление и очистка nil-карты безопасны и не выделяют карту. Паника была бы при добавлении элемента, а не при delete или clear.');
q('Clear среза не меняет длину','a:=[]int{1,2,3};clear(a[1:]);fmt.Println(a,len(a))','[1 0 0] 3',['[1] 1','[] 0','panic'],'Clear обнуляет элементы переданного среза; не меняет его заголовок и не удаляет позиции из массива.');
q('NaN-ключ не находится даже собой','n:=math.NaN();m:=map[float64]int{n:7};v,ok:=m[n];delete(m,n);fmt.Println(v,ok,len(m));clear(m);fmt.Println(len(m))','0 false 1\n0',['7 true 0\n0','0 false 0\n0','panic'],'NaN не равен самому себе, поэтому lookup и delete не находят такой ключ. Clear удаляет все записи, не выполняя поиск по равенству ключа.','','fmt,math');
q('Массив из среза указателей копируется поверхностно','x,y:=1,2;s:=[]*int{&x,&y};a:=[2]*int(s);s[0]=&y;*a[0]=9;fmt.Println(x,*s[0],*a[0],a[0]==s[0])','9 2 9 false',['1 9 9 true','9 9 9 true','panic'],'Преобразование копирует указатели в отдельный массив. Замена s[0] не меняет a[0], но запись через скопированный указатель a[0] меняет исходную x.');
q('Указатель на массив сохраняет общий буфер','s:=[]int{1,2};a:=(*[2]int)(s);s[0]=9;fmt.Println(*a,s)','[9 2] [9 2]',['[1 2] [9 2]','[1 2] [1 2]','panic'],'Преобразование в *[2]int ссылается на начальные элементы того же массива среза. Длины 2 достаточно, копирования нет.');
q('Нулевые массивы и nilness исходного среза','var a []int;b:=make([]int,0);pa:=(*[0]int)(a);pb:=(*[0]int)(b);fmt.Println(pa==nil,pb==nil,[0]int(a)==[0]int(b))','true false true',['true true true','false false true','panic'],'Указатель из nil-среза равен nil; из ненулевого пустого среза — нет. Сами массивы длины ноль равны: у них нет различающихся элементов.');
q('Строковый ключ из изменяемых байтов','b:=[]byte("go");m:=map[string]int{string(b):7};b[0]=\'n\';fmt.Println(m["go"],m[string(b)],string(b))','7 0 no',['0 7 no','7 7 no','panic'],'Ключ карты хранит неизменную строку go. Изменение исходных байтов создаёт при следующем преобразовании другую строку no, которой в карте нет.');
section('Экзамен · Generics, callback и ленивые вычисления вместе');
q('Generic Map сохраняет именованный выход','x:=Map[IDs]([]string{"go","types"},func(s string)int{return len(s)});fmt.Printf("%T %v",x,x)','main.IDs [2 5]',['[]int [2 5]','main.IDs [0 0]','Не компилируется'],'Первым явно задаётся тип выходного контейнера S. Входной A выводится как string, B как int из callback и ограничения S.','type IDs []int;func Map[S ~[]B,A,B any](xs []A,f func(A)B)S{out:=make(S,len(xs));for i,x:=range xs{out[i]=f(x)};return out}');
q('Fold с разными типами элемента и аккумулятора','v:=Fold([]int{2,3},"n",func(s string,x int)string{return fmt.Sprint(s,x)});fmt.Println(v)','n23',['n5','23n','Не компилируется'],'A=int и B=string выводятся независимо. Fold последовательно передаёт новый строковый аккумулятор следующему вызову callback.','func Fold[A,B any](xs []A,z B,f func(B,A)B)B{for _,x:=range xs{z=f(z,x)};return z}');
q('Композиция меняет промежуточный тип','f:=Compose(func(s string)int{return len(s)},func(n int)bool{return n%2==0});fmt.Println(f("go"),f("golang!"))','true false',['false true','2 7','Не компилируется'],'Compose связывает результат первой функции с аргументом второй: string → int → bool. Порядок применения задан телом, а не названием.','func Compose[A,B,C any](f func(A)B,g func(B)C)func(A)C{return func(x A)C{return g(f(x))}}');
bad('Несогласованный промежуточный тип композиции','f:=Compose(func(s string)int{return len(s)},func(n int64)bool{return n>0});fmt.Println(f("go"))','does not match inferred type',['true','false','panic'],'Один параметр B должен совпасть с int результата f и int64 аргумента g. Неявного числового адаптера вывод типов не создаёт.','func Compose[A,B,C any](f func(A)B,g func(B)C)func(A)C{return func(x A)C{return g(f(x))}}');
q('Generic Filter изменяет исходный массив','a:=[]int{1,2,3,4};b:=Filter(a,func(x int)bool{return x%2==0});fmt.Println(a,b)','[2 4 3 4] [2 4]',['[1 2 3 4] [2 4]','[2 4 0 0] [2 4]','panic'],'Filter использует xs[:0] как буфер результата и перезаписывает начало общего массива. Этот пользовательский алгоритм не очищает хвост.','func Filter[T any](xs []T,p func(T)bool)[]T{out:=xs[:0];for _,x:=range xs{if p(x){out=append(out,x)}};return out}');
q('Memoize отличает нулевой результат от промаха','n:=0;f:=Memo(func(x int)int{n++;return 0});fmt.Println(f(2),f(2),n)','0 0 1',['0 0 2','2 2 1','Не компилируется'],'Двухрезультатный lookup проверяет присутствие ключа независимо от значения. Поэтому нулевой результат тоже кэшируется.','func Memo[K comparable,V any](f func(K)V)func(K)V{cache:=map[K]V{};return func(k K)V{if v,ok:=cache[k];ok{return v};v:=f(k);cache[k]=v;return v}}');
q('Memoize с any принимает несравнимый ключ статически','defer func(){fmt.Println(recover()!=nil)}();f:=Memo[any](func(x any)int{return 1});fmt.Println(f([]int{1}))','true',['1','false','Не компилируется'],'Any разрешён как K comparable, но динамический срез нельзя хешировать. Паника возникает при первом обращении к cache до вызова вычисляющего callback.','func Memo[K comparable,V any](f func(K)V)func(K)V{cache:=map[K]V{};return func(k K)V{if v,ok:=cache[k];ok{return v};v:=f(k);cache[k]=v;return v}}');
q('Одна фабрика — независимые кэши','n:=0;base:=func(x int)int{n++;return x};a:=Memo(base);b:=Memo(base);a(1);a(1);b(1);fmt.Println(n)','2',['1','3','0'],'Каждый вызов Memo создаёт собственную карту. Функция base и её счётчик общие, но результат a не заполняет кэш b.','func Memo[K comparable,V any](f func(K)V)func(K)V{cache:=map[K]V{};return func(k K)V{if v,ok:=cache[k];ok{return v};v:=f(k);cache[k]=v;return v}}');
q('Option Some с nil остаётся присутствующим','o:=Some[*int](nil);v,ok:=o.Get();fmt.Println(ok,v==nil)','true true',['false true','true false','panic'],'Наличие хранится отдельным bool. Nil — допустимое значение T=*int и не означает отсутствия Some.','type Option[T any]struct{v T;ok bool};func Some[T any](v T)Option[T]{return Option[T]{v,true}};func(o Option[T])Get()(T,bool){return o.v,o.ok}');
q('Нулевая Option не вызывает Map callback','n:=0;var o Option[int];r:=MapOption(o,func(x int)string{n++;return "x"});fmt.Println(r.ok,n)','false 0',['true 1','false 1','Не компилируется'],'Нулевой Option имеет ok=false. Адаптер возвращает нулевой Option результата и не вычисляет callback для отсутствующего значения.','type Option[T any]struct{v T;ok bool};func MapOption[A,B any](o Option[A],f func(A)B)Option[B]{if !o.ok{return Option[B]{}};return Option[B]{f(o.v),true}}');
q('Ленивый Map ещё не вызывает callback','n:=0;seq:=Map(slices.Values([]int{1,2}),func(x int)int{n++;return x*2});fmt.Print(n," ");fmt.Println(slices.Collect(seq),n)','0 [2 4] 2',['2 [2 4] 2','0 [2 4] 0','Не компилируется'],'Map возвращает итератор-функцию. Преобразования происходят только при обходе Collect, по одному на переданный элемент.','func Map[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for x:=range s{if !yield(f(x)){return}}}}','fmt,iter,slices');
q('Break прекращает ленивое преобразование','n:=0;seq:=Map(slices.Values([]int{1,2,3}),func(x int)int{n++;return x*2});for x:=range seq{fmt.Print(x," ");break};fmt.Println(n)','2 1',['2 3','2 4 6 3','panic'],'После break yield возвращает false. Map немедленно выходит и не вызывает преобразование для остальных элементов.','func Map[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for x:=range s{if !yield(f(x)){return}}}}','fmt,iter,slices');
q('Повторный обход повторяет эффекты','n:=0;seq:=Map(slices.Values([]int{1,2}),func(x int)int{n++;return x});slices.Collect(seq);slices.Collect(seq);fmt.Println(n)','4',['2','0','panic'],'Данный итератор повторно обходит исходный срез при каждом вызове. Он не кэширует результаты и не является автоматически одноразовым.','func Map[A,B any](s iter.Seq[A],f func(A)B)iter.Seq[B]{return func(yield func(B)bool){for x:=range s{if !yield(f(x)){return}}}}','fmt,iter,slices');
q('Values фиксирует длину, но видит элементы','s:=make([]int,2,3);s[0]=1;s[1]=2;seq:=slices.Values(s);s[0]=9;s=append(s,3);fmt.Println(slices.Collect(seq))','[9 2]',['[1 2]','[9 2 3]','panic'],'Values получает копию заголовка длины 2. Общий массив позволяет увидеть запись 9, но изменение длины переменной s не расширяет итератор.','','fmt,slices');
q('Итератор нарушает сигнал остановки','defer func(){fmt.Println(recover()!=nil)}();seq:=func(yield func(int)bool){yield(1);yield(2)};for range seq{break}','true',['false','2','Не компилируется'],'После break yield уже вернул false. Повторный вызов yield нарушает протокол range-over-func и вызывает runtime panic.');
q('Defer итератора выполняется при break','seq:=func(yield func(int)bool){defer fmt.Print("end ");if !yield(1){return};yield(2)};for x:=range seq{fmt.Print(x," ");break};fmt.Println("done")','1 end done',['1 done end','1 2 end done','panic'],'Break возвращает false из yield; итератор выходит, исполняет свой defer, и только затем управление достигает оператора после range.');
q('Pull явно завершает при stop','done:=false;seq:=func(yield func(int)bool){defer func(){done=true}();for i:=0;i<3;i++{if !yield(i){return}}};next,stop:=iter.Pull[int](seq);v,ok:=next();fmt.Print(v," ",ok," ",done," ");stop();fmt.Println(done)','0 true false true',['0 true true true','0 false false true','deadlock'],'После next итератор приостановлен в yield и defer ещё не выполнен. Stop завершает обход и дожидается выхода итератора.','','fmt,iter');
q('Next после stop возвращает ноль и false','next,stop:=iter.Pull(slices.Values([]string{"go","types"}));next();stop();v,ok:=next();fmt.Printf("%q %v",v,ok)','"" false',['"types" true','"go" true','panic'],'После stop итератор завершён. Дальнейшие next безопасно возвращают нулевое значение элемента и false, не возобновляя источник.','','fmt,iter,slices');
q('Generic стратегия хранит указательный счётчик','c:=&Counter{};fmt.Println(Run[int](c,[]int{2,3}),c.N)','5 2',['5 0','3 2','Не компилируется'],'Стратегия реализуется указателем *Counter. Generic-алгоритм вызывает её метод для каждого элемента; состояние счётчика остаётся в общем объекте.','type Strategy[T any]interface{Apply(T)T};type Counter struct{N int};func(c *Counter)Apply(x int)int{c.N++;return x};func Run[T ~int,S Strategy[T]](s S,xs []T)T{var sum T;for _,x:=range xs{sum+=s.Apply(x)};return sum}');
q('Reflect вызывает инстанцированный generic-адаптер','f:=reflect.ValueOf(Compose[int,string,bool](func(x int)string{return strings.Repeat("x",x)},func(s string)bool{return len(s)>2}));r:=f.Call([]reflect.Value{reflect.ValueOf(3)});fmt.Println(r[0].Bool(),f.Type().NumIn())','true 1',['true 2','false 1','Не компилируется'],'После инстанциации и композиции получается обычная функция func(int)bool. Reflect видит её конкретную сигнатуру с одним аргументом.','func Compose[A,B,C any](f func(A)B,g func(B)C)func(A)C{return func(x A)C{return g(f(x))}}','fmt,reflect,strings');
